// The model is generated by the plugin, from the description Sample.WebServer's build writes beside
// this file, and again whenever that build writes a new one. The page asks for /api, which the dev
// server forwards to Sample.WebServer, so the page and the API share an origin and the server needs no
// cross-origin policy; live queries and pending commands stream through the forward as they arrive.
//
// SCRY_SERVER points the forward at a server other than Sample.WebServer's own launch profile's.
// SCRY_DESCRIPTION reads another description: CI builds this from the sample model's committed one.

import { defineConfig } from "vite";
import { scry } from "scry-client/vite";

// begin-snippet: typescriptWebViteConfig
export default defineConfig({
  plugins: [
    scry({ input: process.env["SCRY_DESCRIPTION"] ?? "scry.description.json", output: "src/scry.generated.ts" })
  ],
  server: {
    proxy: {
      "/api": process.env["SCRY_SERVER"] ?? "http://localhost:5000"
    }
  },
  // A page per sample, as the Blazor sample has.
  build: {
    rolldownOptions: {
      input: ["index.html", "paging.html", "keyset.html", "permissions.html", "live.html", "commands.html"]
    }
  }
});
// end-snippet
